\cite{Duan23}\label{def_Gn}
For an integer $t \geq 2$, let $K_{\lceil \frac{t}{2} \rceil}$ and $K_{\lfloor \frac{t}{2} \rfloor}$ be vertex-disjoint complete graphs with vertex sets
\[
V = \{r_1, r_2, \ldots, r_{\lceil \frac{t}{2} \rceil}\}
\quad\text{and}\quad
W = \{w_1, w_2, \ldots, w_{\lfloor \frac{t}{2} \rfloor}\},
\]
respectively. Let $N_W(x)$ denote the neighborhood of any vertex $x$ in $W$. Let  $G_t$ (see Figure \ref{fig:G8} for $t=8$ and Figure \ref{fig:G9} for $t=9$) be the graph obtained by applying the following operations:
\begin{itemize}
\item If $t$ is even, we insert new edges such that
\begin{align*}
&N_W(r_1) = \varnothing \subset N_W(r_2) = \{w_{\frac{t}{2}}\} \subset N_W(r_3) = \{w_{\frac{t}{2}}, w_{\frac{t}{2}-1}\} \subset \cdots \\
&\subset N_W(r_{\frac{t}{2}-1}) = \{w_{\frac{t}{2}}, w_{\frac{t}{2}-1}, \ldots, w_3\} 
\subset N_W(r_{\frac{t}{2}}) = \{w_{\frac{t}{2}}, w_{\frac{t}{2}-1}, \ldots, w_2\}.
\end{align*}
\item For $t$ odd, we insert new edges such that
\begin{align*}
&N_W(r_1) = \varnothing \subset N_W(r_2) = \{w_{\frac{t-1}{2}}\} \subset N_W(r_3) = \{w_{\frac{t-1}{2}}, w_{\frac{t-1}{2}-1}\} \subset \cdots \\
&\subset N_W(r_{\frac{t+1}{2}-1}) = \{w_{\frac{t-1}{2}}, w_{\frac{t-1}{2}-1}, \ldots, w_2\} 
\subset N_W(r_{\frac{t+1}{2}}) = \{w_{\frac{t-1}{2}}, w_{\frac{t-1}{2}-1}, \ldots, w_1\}.
\end{align*}
\end{itemize}

Note that when $t$ is odd, the above construction of $G_t$ can equivalently be obtained using $G_{t-1}$ by adding the vertex $r_{\frac{t+1}{2}}$ and joining it to all the vertices of $G_{t-1}$.

\cite[Theorem 2.18]{Oboudi}\label{thm:Oboudi}
Let $G$ be a graph of order $n \geq 3$ with two positive eigenvalues and zero nullity. 
\begin{itemize}
    \item[(i)] If $G$ is disconnected, then $G$ is isomorphic to the disjoint union of $K_{n_1}$ and $K_{n_2}$ for some integers $n_1, n_2 \geq 2$;
    \item[(ii)] If $G$ is connected, then $G$ is isomorphic to $B_t({n_1}, {n_2}, \ldots, {n_t})$, where  $3  \leq t \leq 12$ and $n_1 + n_2 + \cdots + n_t = n$,  for some positive integers $n_1, n_2, \ldots, n_t$.
\end{itemize}

\cite[Theorem 2.21]{Oboudi}\label{thm:char_polynomial} 
Let $t \ge 2$ be an integer and let $G_t$ be a graph on $t$ vertices with adjacency matrix $A = [a_{ij}]$.  Let $n_1, \ldots, n_t$ be some positive integers such that $n_1 + \cdots + n_t=n$.
Define the $t \times t$ matrix $M = [m_{ij}]$ by
\begin{equation*}
m_{ij} := 
\begin{cases}
n_i - 1, & \text{if } i = j,\\[2pt]
a_{ij}n_j, & \text{if } i \neq j.
\end{cases}
\end{equation*}
Then the eigenvalues of $B_t({n_1}, \ldots, {n_t})$  are $-1$ with multiplicity  $n - t$ and the rest of the eigenvalues are the eigenvalue of $M$. Moreover, for a fixed vertex ordering of $G_t$, the matrix $M$ admits a nice block structure.

\label{trace_even}
Let $M$ be the $2s \times 2s$ matrix as defined in Theorem~\ref{thm:char_polynomial}. Then
\begin{equation}\label{eq:13}
       \operatorname{tr}(M^2) = \sum_{i=1}^{2s} \lambda_i^2 = \left( \sum_{i=1}^{s} n_i \right)^2 + \left( \sum_{i=s+1}^{2s} n_i \right)^2 + 2 \sum_{i=2}^{s} \sum_{j=2s-i+2}^{2s} n_{i} n_{j} - 2n + 2s.
   \end{equation}

Since $\operatorname{tr}(M^2)=\sum_{i,k} m_{ik}m_{ki}$. Using the definition of $M$,
\begin{equation*}
    \operatorname{tr}(M^2)
=\sum_{i=1}^{2s}(n_i-1)^2
\;+\;\sum_{i\neq j} a_{ij}a_{ji}\,n_in_j.
\end{equation*}
Since $A(G_{2s})$ is symmetric, $a_{ij}=a_{ji}\in\{0,1\}$, so
\begin{equation}\label{eq:111}
    \operatorname{tr}(M^2)
=\sum_{i=1}^{2s}(n_i-1)^2 \;+\; 2\!\!\sum_{1\le i<j\le 2s}\!\! a_{ij}\,n_in_j.
\end{equation}

Let us now simplify the last term of \eqref{eq:111}. To do so, we partition the edge set of $G_{2s}$ according to the block structure of its adjacency matrix.
The subgraph of $G_{2s}$ induced by the first $s$ vertices is a clique thus
\begin{equation*}
    2\sum_{1\le i<j\le s} n_i n_j
    = \Bigl(\sum_{i=1}^{s} n_i\Bigr)^2 - \sum_{i=1}^{s} n_i^2.
\end{equation*}
Similarly, the subgraph of $G_{2s}$ induced by the last $s$ vertices is a clique and 
\begin{equation*}
    2\sum_{s+1\le i<j\le 2s} n_i n_j
    = \Bigl(\sum_{i=s+1}^{2s} n_i\Bigr)^2 - \sum_{i=s+1}^{2s} n_i^2.
\end{equation*}
The remaining edges in $G_{2s}$ join the first and last $s$ vertices as in Definition \ref{def_Gn}. These edges (say crossing edges) are 
\begin{equation*}
    E_{\mathrm{cross}}
    = \{(i,j): 2 \le i \le s,\;\; 2s-i+2 \le j \le 2s\},
\end{equation*}
and therefore they contribute
\begin{equation*}
    2\sum_{i=2}^{s} \;\sum_{j=\,2s-i+2}^{\,2s} n_i n_j.
\end{equation*}




Substituting these three pieces into \eqref{eq:111} gives
\begin{align*}
    \operatorname{tr}(M^2)
&=\sum_{i=1}^{2s}(n_i-1)^2 \;+\Bigl(\sum_{i=1}^{s} n_i\Bigr)^2 - \sum_{i=1}^{s} n_i^2+\Bigl(\sum_{i=s+1}^{2s} n_i\Bigr)^2 - \sum_{i=s+1}^{2s} n_i^2+ 2\sum_{i=2}^{s} \;\sum_{j=\,2s-i+2}^{\,2s} n_i n_j\\
&= \Bigl(\sum_{i=1}^{s}n_i\Bigr)^2
 + \Bigl(\sum_{i=s+1}^{2s}n_i\Bigr)^2
 + 2\sum_{i=2}^{s} \sum_{j=\,2s-i+2}^{\,2s} n_i n_j+ \sum_{i=1}^{2s}(n_i-1)^2 - \sum_{i=1}^{2s}n_i^2\\
 &= \Bigl(\sum_{i=1}^{s}n_i\Bigr)^2
 + \Bigl(\sum_{i=s+1}^{2s}n_i\Bigr)^2
 + 2\sum_{i=2}^{s} \sum_{j=\,2s-i+2}^{\,2s} n_i n_j+ \sum_{i=1}^{2s}(n_i^2-2n_i+1) - \sum_{i=1}^{2s}n_i^2
\end{align*}













and simplifying the last two terms yields $-2n+2s$. This yields the claimed formula.

\label{trace_odd} 
Let $M$ be the $(2s+1) \times (2s+1)$ matrix as defined in Theorem~\ref{thm:char_polynomial}. Then
\begin{align*}
    \operatorname{tr}(M^2)
=\sum_{i=1}^{2s+1}\lambda_i^2=\Bigl(\sum_{i=1}^{s}n_i\Bigr)^2
 + \Bigl(\sum_{i=s+1}^{2s}n_i\Bigr)^2
 &+ 2\sum_{i=2}^{s}\sum_{j=\,2s-i+2}^{\,2s} n_i n_j \notag
 \\
&- n_{2s+1}^2
 + 2n\,n_{2s+1}
 + (2s+1) - 2n.
\end{align*}

\label{obs:incomparable}
For the family of graphs $B_t(n_1,\hdots, n_t)$, the bounds \textnormal{(A)} and \textnormal{(B)} are incomparable:
there exist graphs for which \textnormal{(A)} is stronger and graphs for which \textnormal{(B)} is stronger.

\label{thm:omega-odd-3}
Let $G=B_{3}(n_1, n_2, n_3)$ be a graph of order $n$ with positive integers $n_1,n_2,n_3$. Let $\lambda_1,\lambda_2,\lambda_3$ be the adjacency eigenvalues of $G$ different from $-1$. If $(n_1,n_2)\neq (1,1)$, then
\begin{equation}\label{eq:omega-odd-3}
\sqrt{\lambda_1^2+\lambda_2^2+\lambda_3^2}\ \le\ n \left(1-\frac{1}{\omega}\right).
\end{equation}
In particular, for $n_1=n_2=1$ and $n_3\ge 1$, the inequality \eqref{eq:omega-odd-3} does not hold.

Define
\begin{equation*}\label{eq:def-pqn-omega}
n:=n_1+n_2+n_3,\qquad \omega:=\max\{n_1+n_3,n_2+n_3\}.
\end{equation*}
We consider three cases: $n_1>n_2$, $n_1<n_2$, and $n_1=n_2$.\\

\noindent\textbf{Case 1: $n_1>n_2$.}\\

By Theorem~\ref{trace_odd} with $s=1$,
\begin{equation}\label{eq:case1-trace}
\lambda_1^2+\lambda_2^2+\lambda_3^2
= n_1^2+n_2^2 - n_3^2 + 2n\,n_3 + 3 - 2n,
\end{equation}
Since $\omega=n_1+n_3$ in this case, squaring
\eqref{eq:omega-odd-3} and using $\lambda_1^2+\lambda_2^2+\lambda_3^2\ge 0$,
we obtain the equivalent inequality
\begin{equation}\label{eq:case1-goal-squared}
\lambda_1^2+\lambda_2^2+\lambda_3^2
\ \le\ 
n^2\left(1-\frac{1}{n_1+n_3}\right)^2 .
\end{equation}
Substituting $n=n_1+n_2+n_3$ into \eqref{eq:case1-trace} gives
\begin{equation}\label{eq:case1-sumlambda-expanded}
\lambda_1^2+\lambda_2^2+\lambda_3^2
=
n_1^2+n_2^2-n_3^2+2(n_1+n_2+n_3)n_3+3-2(n_1+n_2+n_3).
\end{equation}

Define
\begin{equation*}\label{eq:case1-Delta-def}
\Delta(n_1,n_2,n_3)
:=
n^2\left(1-\frac{1}{n_1+n_3}\right)^2
-\bigl(\lambda_1^2+\lambda_2^2+\lambda_3^2\bigr).
\end{equation*}
Then \eqref{eq:case1-goal-squared} is equivalent to
\begin{equation}\label{eq:case1-Delta-nonneg}
\Delta(n_1,n_2,n_3)\ge 0.
\end{equation}
Clearing denominators using \eqref{eq:case1-sumlambda-expanded} yields
\begin{equation}\label{eq:case1-Delta-D}
\Delta(n_1,n_2,n_3)=\frac{D(n_1,n_2,n_3)}{(n_1+n_3)^2},
\end{equation}
where
\begin{equation}\label{eq:case1-D-def}
\begin{aligned}
D(n_1,n_2,n_3)
=\ &(n_1+n_3-1)^2(n_1+n_2+n_3)^2\\
&-(n_1+n_3)^2\Bigl(n_1^2+n_2^2-n_3^2+2(n_1+n_2+n_3)n_3+3-2(n_1+n_2+n_3)\Bigr).
\end{aligned}
\end{equation}
Since $(n_1+n_3)^2>0$, by \eqref{eq:case1-Delta-D} the condition
\eqref{eq:case1-Delta-nonneg} is equivalent to
\begin{equation}\label{eq:case1-D-nonneg}
D(n_1,n_2,n_3)\ge 0.
\end{equation}

Now fix $n_1$ and $n_3$ and write $D(n_2):=D(n_1,n_2,n_3)$ for $n_2\in[1,n_1-1]$.
Set
\begin{equation*}\label{eq:case1-a}
a:=n_1+n_3.
\end{equation*}
A direct expansion of \eqref{eq:case1-D-def} shows that $D(n_2)$ is a quadratic
polynomial in the single variable $n_2$:
\begin{equation*}\label{eq:case1-D-quadratic}
D(n_2)=(1-2a)\,n_2^2+\beta(n_1,n_3)\,n_2-2a^2,
\end{equation*}
where
\begin{equation*}\label{eq:case1-beta}
\beta(n_1,n_3)
:=2n_1^3+4n_1^2n_3-2n_1^2+2n_1n_3^2-4n_1n_3+2n_1-2n_3^2+2n_3 .
\end{equation*}
Since $n_1,n_3\ge 1$, we have $a\ge 2$, hence
\begin{equation*}\label{eq:case1-concave}
1-2a<0,
\end{equation*}
so $D(n_2)$ is concave down on $\mathbb{R}$. Therefore, on the interval $[1,n_1-1]$ its
minimum is attained at an endpoint:
\begin{equation}\label{eq:case1-endpoint-reduction}
\min_{\,n_2\in[1,n_1-1]} D(n_2)=\min\{D(1),D(n_1-1)\}.
\end{equation}
It thus suffices to prove
\begin{equation*}\label{eq:case1-endpoints-suffice}
D(1)\ge 0
\qquad\text{and}\qquad
D(n_1-1)\ge 0.
\end{equation*}





































\smallskip

Now substituting $n_2=1$ into \eqref{eq:case1-D-def} and simplifying yields
\begin{equation*}\label{eq:case1-D1}
D(1)=D(n_1,1,n_3)=2(n_1-2)(n_1+n_3)^2+1=2(n_1-2)a^2+1.
\end{equation*}
Since $n_1>n_2\ge 1$, we have $n_1\ge 2$. If $n_1=2$, then $D(1)=1$.
If $n_1\ge 3$, then $n_1-2\ge 1$ and $a^2>0$, hence $D(1)\ge 1$.
Thus
\begin{equation}\label{eq:case1-D1-nonneg}
D(1)\ge 1.
\end{equation}

\smallskip

Substituting $n_2=n_1-1$ into \eqref{eq:case1-D-def} and simplifying gives
\begin{equation}\label{eq:case1-Dn1m1}
D(n_1-1)=D(n_1,n_1-1,n_3)
=(n_1-1)^2+2(n_1-2)a\bigl(n_1a-(n_1-1)\bigr).
\end{equation}
If $n_1=2$, then $n_2=1$ and $D(n_1-1)=D(1)=1$.
Assume $n_1\ge 3$. Then $n_1-2>0$ and $a=n_1+n_3\ge n_1+1\ge 4$, and
\begin{equation*}\label{eq:case1-bracket-pos}
n_1a-(n_1-1)=n_1(a-1)+1\ge 1.
\end{equation*}
Hence the second term in \eqref{eq:case1-Dn1m1} is nonnegative, so
\begin{equation}\label{eq:case1-Dn1m1-nonneg}
D(n_1-1)\ge (n_1-1)^2\ge 1.
\end{equation}

Combining \eqref{eq:case1-endpoint-reduction}, \eqref{eq:case1-D1-nonneg},
and \eqref{eq:case1-Dn1m1-nonneg}, we obtain $D(n_2)\ge 0$ for all
$n_2\in[1,n_1-1]$. Therefore \eqref{eq:case1-D-nonneg} holds, which implies
\eqref{eq:case1-Delta-nonneg} by \eqref{eq:case1-Delta-D}, hence
\eqref{eq:case1-goal-squared} and thus \eqref{eq:omega-odd-3}.
This completes the proof of Case~1.


\smallskip
\noindent\textbf{Case 2: $n_1<n_2$.}\\
This case is symmetric to Case~1 after interchanging the roles of $n_1$ and $n_2$, so the same argument proves \eqref{eq:omega-odd-3}.

\smallskip
\noindent\textbf{Case 3: $n_1=n_2$.}\\
Set $t:=n_1=n_2$.                                 
Recall $n=n_1+n_2+n_3=2t+n_3$ and
\begin{equation*}\label{eq:case2-omega}
\omega=\max\{n_1+n_3,n_2+n_3\}=t+n_3.
\end{equation*}
By Theorem~\ref{trace_odd} with $s=1$,
\begin{equation}\label{eq:case2-trace}
\lambda_1^2+\lambda_2^2+\lambda_3^2
= n_1^2+n_2^2-n_3^2+2nn_3+3-2n.
\end{equation}
Substituting $n_1=n_2=t$ and $n=2t+n_3$ into \eqref{eq:case2-trace} yields
\begin{equation}\label{eq:case2-sumlambda}
\lambda_1^2+\lambda_2^2+\lambda_3^2
= n_3^2+4tn_3-2n_3+2t^2-4t+3.
\end{equation}

Since $\omega\geq t+n_3$, squaring \eqref{eq:omega-odd-3} and using
$\lambda_1^2+\lambda_2^2+\lambda_3^2\ge 0$ gives the equivalent inequality
\begin{equation}\label{eq:case2-goal-squared}
\lambda_1^2+\lambda_2^2+\lambda_3^2
\ \le\
n^2\left(1-\frac{1}{t+n_3}\right)^2.
\end{equation}
Define
\begin{equation*}\label{eq:case2-Delta}
\Delta(t,n_3)
:=
n^2\left(1-\frac{1}{t+n_3}\right)^2
-\bigl(\lambda_1^2+\lambda_2^2+\lambda_3^2\bigr),
\qquad n=2t+n_3.
\end{equation*}
Then \eqref{eq:case2-goal-squared} is equivalent to
\begin{equation}\label{eq:case2-Delta-nonneg}
\Delta(t,n_3)\ge 0.
\end{equation}
Clearing denominators (using \eqref{eq:case2-sumlambda}) gives
\begin{equation}\label{eq:case2-Delta-D}
\Delta(t,n_3)=\frac{D(t,n_3)}{(t+n_3)^2},
\end{equation}
where
\begin{equation}\label{eq:case2-D-def}
D(t,n_3)
:=(t+n_3-1)^2(2t+n_3)^2-(t+n_3)^2\bigl(n_3^2+4tn_3-2n_3+2t^2-4t+3\bigr).
\end{equation}
Since $(t+n_3)^2>0$, by \eqref{eq:case2-Delta-D} it suffices to prove
\begin{equation}\label{eq:case2-D-nonneg}
D(t,n_3)\ge 0 \qquad (t\ge 2,\ n_3\ge 1).
\end{equation}


A direct expansion of \eqref{eq:case2-D-def} shows that $D(t,n_3)$
is a quadratic polynomial in the single variable $n_3$:
\begin{equation*}\label{eq:case2-D-quadratic}
D(t,n_3)=A(t)\,n_3^2+B(t)\,n_3+C(t),
\end{equation*}
where
\begin{equation*}\label{eq:case2-ABC}
A(t)=2(t^2-t-1),\qquad
B(t)=2t(2t^2-3t-1),\qquad
C(t)=t^2(2t^2-4t+1).
\end{equation*}

For $t\ge 2$, we have $A(t)>0$ and $B(t)>0$. Hence for every $n_3\ge 1$,
\begin{equation*}\label{eq:case2-monotone}
D(t,n_3)-D(t,1)=A(t)(n_3^2-1)+B(t)(n_3-1)\ \ge\ 0.
\end{equation*}
So the minimum over $n_3\ge 1$ is attained at $n_3=1$:
\begin{equation}\label{eq:case2-reduction-n3}
D(t,n_3)\ge D(t,1)\qquad (t\ge 2,\ n_3\ge 1).
\end{equation}
Substituting $n_3=1$ into \eqref{eq:case2-D-def} gives
\begin{equation*}\label{eq:case2-D-at-1}
D(t,1)=2t^4-3t^2-4t-2.
\end{equation*}
Using $2(t-1)^2\ge 0$, we have $-4t\ge -2t^2-2$, and therefore
\begin{equation*}\label{eq:case2-lowerbound}
D(t,1)=2t^4-3t^2-4t-2\ \ge\ 2t^4-5t^2-4.
\end{equation*}
The polynomial $\phi(t):=2t^4-5t^2-4$ is increasing for $t\ge 2$ since
\begin{equation*}\label{eq:case2-phi-derivative}
\phi'(t)=8t^3-10t=2t(4t^2-5)>0\qquad (t\ge 2),
\end{equation*}
and $\phi(2)=8>0$. Hence
\begin{equation}\label{eq:case2-D1-positive}
D(t,1)\ge 0 \qquad (t\ge 2).
\end{equation}
Combining \eqref{eq:case2-reduction-n3} and \eqref{eq:case2-D1-positive} yields
$D(t,n_3)\ge 0$ for all $t\ge 2$ and $n_3\ge 1$. Consequently,
\eqref{eq:case2-D-nonneg} holds, which implies \eqref{eq:case2-Delta-nonneg} by
\eqref{eq:case2-Delta-D}, and therefore \eqref{eq:case2-goal-squared} and
\eqref{eq:omega-odd-3}. This completes the proof of Case~3 when $t\ge 2$.

Now consider $t=1$. Then $n_1=n_2=1$ and $n_3\ge 1$, and hence
\begin{equation}\label{eq:t1-n-omega}
n=n_1+n_2+n_3=n_3+2,
\qquad
\omega=\max\{1+n_3,1+n_3\}=n_3+1.
\end{equation}
Substituting $t=1$ into \eqref{eq:case2-sumlambda} gives
\begin{equation*}\label{eq:t1-sumsq}
\lambda_1^2+\lambda_2^2+\lambda_3^2
=n_3^2+4n_3-2n_3+2-4+3
=(n_3+1)^2,
\end{equation*}
and hence
\begin{equation}\label{eq:t1-root}
\sqrt{\lambda_1^2+\lambda_2^2+\lambda_3^2}=n_3+1.
\end{equation}
We can rewrite \eqref{eq:omega-odd-3} as
\begin{equation}\label{eq:omega-odd-31}
\frac{n}{\,n-\sqrt{\lambda_1^2+\lambda_2^2+\lambda_3^2}\,}\ \le\ \omega.
\end{equation}
Substituting \eqref{eq:t1-n-omega} and \eqref{eq:t1-root} into \eqref{eq:omega-odd-31} yields
\begin{equation*}\label{eq:t1-contradiction-chain}
\frac{n_3+2}{(n_3+2)-(n_3+1)}\le n_3+1
\quad\Longrightarrow\quad
n_3+2\le n_3+1,
\end{equation*}
which is a contradiction. Therefore \eqref{eq:omega-odd-3} fails for $B_3(1,1,n_3)$.






This completes the proof.

Consider the graph $B_3(2,3,2)$ of order $n=7$ and the associated matrix $M$ of order $t=3$:
\begin{equation*}
M=
\begin{bmatrix}
1&0&2\\
0&2&2\\
2&3&2
\end{bmatrix}.
\end{equation*}
Let $\lambda_1,\lambda_2,\lambda_3$ denote the eigenvalues of $M$. A direct computation gives
\begin{equation}\label{eq:exB3-232-eigsM11}
\lambda_1 \approx 4.52,\quad
\lambda_2 \approx 1.39,\quad
\lambda_3 \approx -1.91.
\end{equation}
Hence, by Theorem~\ref{thm:char_polynomial}, the eigenvalues of $B_3(2,3,2)$ are $-1$ with multiplicity $n-t=4$ together with \eqref{eq:exB3-232-eigsM11}, i.e.,
\begin{equation*}
\operatorname{spec}\bigl(B_3(2,3,2)\bigr)
=\{4.52,\ 1.39,\ -1.91,\ -1,\ -1,\ -1,\ -1\}.
\end{equation*}
Therefore
\begin{equation*}
\sum_{i=1}^{3}\lambda_i^2
\approx (4.52)^2+(1.39)^2+(1.91)^2
\approx 26,
\qquad\text{so}\qquad
\sqrt{\sum_{i=1}^{3}\lambda_i^2}\approx 5.10.
\end{equation*}
Since $\omega=\max\{n_1+n_3,\;n_2+n_3\}=\max\{4,5\}=5$, we have
\begin{equation*}
n\!\left(1-\frac{1}{\omega}\right)=7\!\left(1-\frac{1}{5}\right)=\frac{28}{5}=5.60,
\end{equation*}
and hence the inequality \eqref{eq:omega-odd-3}



holds for $B_3(2,3,2)$.

\label{rem:B3-11n3}
We now verify that the Elphick--Wocjan conjecture holds for $B_3(1,1,n_3)$. Note that $B_3(1,1,n_3)$ is the complete multipartite graph $K_{2,1,1,\ldots,1}$ and consequently it has exactly one positive eigenvalue \cite{Smith1970}. Then $\sqrt{s^+}=\lambda_1$. Thus for this
family the Elphick--Wocjan conjecture is equivalent to the Wilf bound, which always holds.

Consider the graph $B_5(1,2,1,1,1)$ of order $n=6$                                                                                
and the associated matrix $M$ of order $t=5$:
\begin{equation*}
M=
\begin{bmatrix}
0&2&0&0&1\\
1&1&0&1&1\\
0&0&0&1&1\\
0&2&1&0&1\\
1&2&1&1&0
\end{bmatrix}.
\end{equation*}
Let $\lambda_1,\dots,\lambda_5$ denote the eigenvalues of $M$. A direct computation gives
\begin{equation}\label{eq:exB5b-eigsM}
\lambda_1\approx 3.86,\quad
\lambda_2\approx 0.78,\quad
\lambda_3\approx -0.38,\quad
\lambda_4\approx -1.48,\quad
\lambda_5\approx -1.78.
\end{equation}
Hence, by Theorem~\ref{thm:char_polynomial}, the eigenvalues of $B_5(1,2,1,1,1)$ are $-1$ with multiplicity $n-t=1$ together with \eqref{eq:exB5b-eigsM}, i.e.,
\begin{equation*}
\operatorname{spec}\bigl(B_5(1,2,1,1,1)\bigr)
=\{3.86,\ 0.78,\ -0.38,\ -1,\ -1.48,\ -1.78\}.
\end{equation*}

The clique number of $B_5(1,2,1,1,1)$ is $\omega=4$. Therefore
\begin{equation*}
n\!\left(1-\frac{1}{\omega}\right)
=6\!\left(1-\frac{1}{4}\right)
=\frac{9}{2}.
\end{equation*}









For Elphick--Wocjan conjecture,
the positive eigenvalues are $\lambda_1$ and $\lambda_2$, hence
\begin{equation*}
s^+=\lambda_1^2+\lambda_2^2\approx 15.50
\end{equation*}
and thus
\begin{equation*}
\sqrt{s^+}\approx 3.94\ \le\ \frac{9}{2}=n\!\left(1-\frac{1}{\omega}\right).
\end{equation*}

For our bound,
since $\sum_{i=1}^{5}\lambda_i^2=\operatorname{tr}(M^2)$ and $\operatorname{tr}(M^2)=21$, we obtain
\begin{equation*}
\sum_{\lambda\in\operatorname{spec}(M)} \lambda^2=\operatorname{tr}(M^2)=21.
\end{equation*}
Consequently,
\begin{equation*}
\sqrt{\sum_{\lambda\in\operatorname{spec}(M)} \lambda^2}
=\sqrt{21}\approx 4.58 \not\le \frac{9}{2}=n\!\left(1-\frac{1}{\omega}\right).
\end{equation*}



In this example, the Elphick-Wocjan conjecture holds. 
However, our stronger bound fails for $B_5(1,2,1,1,1)$.                                                                                                   
This suggests that, for $t=5$, there may be additional parameter choices for which our bound fails.
